  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });

  it('recovers from a schema-rejected tool call when the provider retries with valid input on the next round', async () => {
    const registry = new ToolRegistry();
    const executorCalls: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        executorCalls.push(input);
        return `sunny in ${String(input.location)}`;
      }
    );

    let rejectionSeenByProvider = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield STOP_FOR_TOOL;
          return;
        }
        if (round !== 2) {
          yield {type: 'text', text: 'It is sunny in Berlin.'};
          yield STOP_DONE;
          return;
        }
        const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
        const firstBlock = lastMessage.content[0];
        rejectionSeenByProvider = firstBlock?.content ?? '';
        yield {type: 'tool_use', toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Berlin'}}};
        yield STOP_FOR_TOOL;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const reply = await orchestrator.processMessage(createSession('weather in Berlin?'));

    expect({
      reply,
      executorCalls,
      providerSawRejection:
        rejectionSeenByProvider.includes('location') && /required/i.test(rejectionSeenByProvider),
    }).toEqual({
      reply: 'It is sunny in Berlin.',
      executorCalls: [{location: 'Berlin'}],
      providerSawRejection: true,
    });
  });
});

